<?php
namespace App\Http\Controllers;
use App\Models\{Category,Product,Purchase,Sale,StockMovement};use Illuminate\Http\Request;use Illuminate\Validation\ValidationException;
class ReportController extends Controller { public function index(Request $r){$stats=['products'=>Product::count(),'units'=>Product::sum('stock'),'value'=>Product::selectRaw('COALESCE(SUM(stock * purchase_price),0) AS total')->value('total'),'in'=>StockMovement::where('type','IN')->sum('quantity'),'out'=>StockMovement::where('type','OUT')->sum('quantity')];$categories=Category::with('products')->withCount('products')->orderBy('name')->get();$categories->each(function($c){$c->inventory_value=$c->products->sum(fn($p)=>$p->stock*$p->purchase_price);$c->total_stock=$c->products->sum('stock');});
 $filters=$r->validate(['from'=>['nullable','date'],'to'=>['nullable','date'],'status'=>['nullable','in:completed,cancelled']]);if(!empty($filters['from'])&&!empty($filters['to'])&&$filters['to']<$filters['from'])throw ValidationException::withMessages(['to'=>'Tanggal akhir harus sama atau setelah tanggal awal.']);$sales=Sale::with('user')->withCount('items')->when($r->filled('from'),fn($q)=>$q->whereDate('sold_at','>=',$filters['from']))->when($r->filled('to'),fn($q)=>$q->whereDate('sold_at','<=',$filters['to']))->when($r->filled('status'),fn($q)=>$q->where('status',$filters['status']))->latest('sold_at')->paginate(15)->withQueryString();return view('reports.index',compact('stats','categories','sales'));} }
